D=CalcDoc('2.1',[116,117,118,119],lambda n:116 if n<=14 else 117 if n<=33 else 118 if n<=53 else 119)
def add(n,st,steps,ans,check,parts=()):return D.add(n,('미분계수·접선·순간변화율','Derivatives, tangents, and instantaneous rates'),st,('평균변화율의 차분몫을 만든 뒤 극한을 취한다. 접선은 점–기울기 식으로 쓴다.','Form the difference quotient and take its limit. Write a tangent using point–slope form.'),steps,ans,check,parts)
x,h,a=s.symbols('x h a',real=True)
def tangfig(n,f,points,bounds,zoom=False):
 fn=s.lambdify(x,f,'math');panels=[]
 cs=[samples(fn,bounds[0],bounds[1])]
 for at in points:
  value=float(f.subs(x,at));der=float(s.diff(f,x).subs(x,at));cs.append([(bounds[0],value+der*(bounds[0]-at)),(bounds[1],value+der*(bounds[1]-at))])
 panels.append(panel('Curve and tangent lines',bounds,cs,[(float(z),float(f.subs(x,z)))for z in points]))
 if zoom:
  at=float(points[0]);val=float(f.subs(x,at));der=float(s.diff(f,x).subs(x,at))
  for w in [.1,.005]:panels.append(panel(f'Zoom around tangent point: half-width {w}',(at-w,at+w,val-abs(der)*w*1.3,val+abs(der)*w*1.3),[samples(fn,at-w,at+w),[(at-w,val-der*w),(at+w,val+der*w)]]))
 D.fig(n,panels)
add(1,('곡선 y=f(x)의 P=(3,f(3)),Q=(x,f(x))에 대해 (a)할선 기울기, (b)P의 접선 기울기 식을 쓰라.','For P=(3,f(3)) and Q=(x,f(x)) on y=f(x), give expressions for (a)the secant slope and (b)the tangent slope at P.'),[('기울기는 세로 변화량을 가로 변화량으로 나눈 값이다. 접선은 Q가 P로 접근할 때의 유한 극한이다.','Slope is the vertical change divided by the horizontal change. The tangent slope is the finite limit as Q approaches P.')],d(r'\text{(a) }\frac{f(x)-f(3)}{x-3},\ x\ne3;\quad\text{(b) }\lim_{x\to3}\frac{f(x)-f(3)}{x-3}=f\prime(3)'),('분모 0인 x=3에서는 할선식이 정의되지 않으며 유한 극한이 존재할 때 접선 기울기를 준다.','The secant expression excludes x=3; an existing finite limit gives the tangent slope.'),list('ab'))
add(2,('y=sin x를 [−2,2]²,[−1,1]²,[−0.5,0.5]²에서 그려 원점 확대 시 모습을 설명하라.','Plot y=sin x in the squares [−2,2]²,[−1,1]²,[−0.5,0.5]² and describe what happens when zooming toward the origin.'),[('구간이 작아질수록 사인 곡선은 원점을 지나는 직선 y=x와 비슷해진다.','On smaller windows the sine curve approaches the appearance of the line y=x through the origin.'),(d(r'\lim_{x\to0}\frac{\sin x-0}{x-0}=1'),d(r'\lim_{x\to0}\frac{\sin x-0}{x-0}=1'))],('원점 근처에서 기울기 1인 직선처럼 보인다.','Near the origin it looks like a straight line of slope 1.'),('sin x−x의 크기는 작은 x에서 약 |x|³/6이므로 확대 시 상대적인 굽음이 줄어든다.','For small x the error sin x−x has magnitude about |x|³/6, so its relative curvature diminishes under zooming.'))
