add(11,('수면 위 100 ft에서 떨어지는 물체의 낙하거리 d(t)=16t² ft이다. (a)수면 도달 시각, (b)그때 속도를 구하라.','A diver starts 100 ft above water, with downward distance d(t)=16t² ft. Find (a)the time of impact and (b)impact velocity.'),[('16t²=100에서 양의 해 t=2.5초를 고른다.','The positive solution of 16t²=100 is t=2.5 seconds.'),(d(r'\lim_{h\to0}\frac{16(t+h)^2-16t^2}{h}=32t'),d(r'\lim_{h\to0}\frac{16(t+h)^2-16t^2}{h}=32t'))],('(a)2.5 s. (b)아래 방향 80 ft/s(위쪽을 양수로 잡으면 −80 ft/s).','(a)2.5 s. (b)80 ft/s downward, or −80 ft/s if upward is positive.'),('낙하거리를 양수로 정의한 방향을 명시하여 높이 좌표의 속도 부호와 구별했다.','Explicitly distinguished positive downward distance from the velocity sign in an upward-positive height coordinate.'),list('ab'))
add(12,('화성에서 H(t)=10t−1.86t² m이다. (a)1초 속도, (b)t=a 속도, (c)지면 재도달 시각, (d)그때 속도를 구하라.','On Mars let H(t)=10t−1.86t² m. Find (a)velocity at 1 second, (b)velocity at t=a, (c)return time to the surface, and (d)impact velocity.'),[(d(r'\frac{H(a+h)-H(a)}h=10-3.72a-1.86h\longrightarrow10-3.72a'),d(r'\frac{H(a+h)-H(a)}h=10-3.72a-1.86h\longrightarrow10-3.72a')),('H(t)=t(10−1.86t)=0의 양의 해는 500/93초이다.','The positive root of H(t)=t(10−1.86t)=0 is 500/93 seconds.')],('(a)6.28 m/s; (b)10−3.72a m/s; (c)500/93≈5.376344 s; (d)−10 m/s.','(a)6.28 m/s; (b)10−3.72a m/s; (c)500/93≈5.376344 s; (d)−10 m/s.'),('재도달 시각을 높이에 대입하면 0, 속도식에 대입하면 −10으로 출발속도와 크기가 같다.','At the return time the height is zero and the velocity is −10, matching the initial speed in magnitude.'),list('abcd'))
add(13,('위치 s(t)=1/t² m인 입자의 속도를 t=a,1,2,3초에서 구하라.','For displacement s(t)=1/t² m, find velocity at t=a,1,2,3 seconds.'),[(d(r'\frac{1/(a+h)^2-1/a^2}{h}=-\frac{2a+h}{a^2(a+h)^2}\longrightarrow-\frac2{a^3}'),d(r'\frac{1/(a+h)^2-1/a^2}{h}=-\frac{2a+h}{a^2(a+h)^2}\longrightarrow-\frac2{a^3}'))],d(r'v(a)=-2/a^3,\quad v(1)=-2,\quad v(2)=-1/4,\quad v(3)=-2/27\ \mathrm{m/s}'),('a>0인 시간 영역에서 위치가 감소하여 속도가 음수라는 결과와 일치한다.','For positive time the displacement decreases, agreeing with the negative velocity.'))
f=x*x/2-6*x+23;windows=[(4,8),(6,8),(8,10),(8,12)];vels=[s.simplify((f.subs(x,b)-f.subs(x,a))/(b-a))for a,b in windows]
add(14,('s(t)=t²/2−6t+23 ft이다. (a)[4,8],[6,8],[8,10],[8,12]의 평균속도, (b)8초 순간속도, (c)네 할선과 접선을 위치곡선과 함께 그려라.','Let s(t)=t²/2−6t+23 ft. Find (a)average velocities on [4,8],[6,8],[8,10],[8,12], (b)instantaneous velocity at 8, and (c)plot the four secants and tangent with the position curve.'),[('각 평균은 (s(b)−s(a))/(b−a)이며 이 이차식에서는 (a+b)/2−6으로 단순화된다.','Each average is (s(b)−s(a))/(b−a), simplifying here to (a+b)/2−6.'),(d(r'v(t)=\lim_{h\to0}(t-6+h/2)=t-6,\quad v(8)=2'),d(r'v(t)=\lim_{h\to0}(t-6+h/2)=t-6,\quad v(8)=2'))],('(a)0,1,3,4 ft/s. (b)2 ft/s. 접선 s=2t−9.','(a)0,1,3,4 ft/s. (b)2 ft/s. Tangent s=2t−9.'),('양쪽의 가까운 평균 1과 3의 평균이 순간속도 2와 일치하며, 접선은 (8,7)을 지난다.','The average of neighboring secant slopes 1 and 3 equals instantaneous slope 2; the tangent passes through (8,7).'),['a(i)','a(ii)','a(iii)','a(iv)','b','c'])
